function updateDocBackupStatus(id,patch){const all=getBackupStatuses();all[id]={...(all[id]||{}),...patch,lastChange:new Date().toISOString()};setBackupStatuses(all);renderSaved();renderQuotes()}
function getDocBackupStatus(id){return getBackupStatuses()[id]||{}}
function backupPillHtml(id){
  const st=getDocBackupStatus(id),local=IS_MOBILE_DEVICE?'ok':(st.local||'setup'),cloud=st.cloud||'setup';
  const one=(kind,label)=>kind==='ok'?`<span class="backup-pill ok">${label} ✓</span>`:kind==='error'?`<span class="backup-pill error">${label} !</span>`:kind==='pending'?`<span class="backup-pill pending">${label} …</span>`:`<span class="backup-pill">${label} ⚙</span>`;
  return `<div class="backup-badges">${one(local,IS_MOBILE_DEVICE?'📱 Teléfono':'💾 Local')}${one(cloud,'☁️ Nube')}</div>`;
}
function backupDocLookup(type,id){return type==='contract'?getContracts().find(x=>x.id===id):getQuotes().find(x=>x.id===id)}
function enqueueDocumentBackup(type,data){
  if(!data?.id)return;
  const q=getBackupQueue().filter(x=>!(x.type===type&&x.id===data.id));
  q.push({type,id:data.id,queuedAt:new Date().toISOString()});
  setBackupQueue(q);
  const cloudReady=Boolean(getCloudConfig().url&&getCloudConfig().anonKey&&getCloudSession()?.access_token);
  updateDocBackupStatus(data.id,{local:IS_MOBILE_DEVICE?'ok':(backupRootHandle?'pending':'setup'),cloud:cloudReady?'pending':'setup'});
  scheduleBackupProcessing();
}
function queueAllCurrentDocuments(force=false){
  const q=getBackupQueue();
  const seen=new Set(q.map(x=>`${x.type}:${x.id}`));
  for(const d of getContracts())if(!seen.has(`contract:${d.id}`)){q.push({type:'contract',id:d.id,queuedAt:new Date().toISOString()});seen.add(`contract:${d.id}`)}
  for(const d of getQuotes())if(!seen.has(`quote:${d.id}`)){q.push({type:'quote',id:d.id,queuedAt:new Date().toISOString()});seen.add(`quote:${d.id}`)}
  setBackupQueue(q);
  for(const d of getContracts()){const st=getDocBackupStatus(d.id);updateDocBackupStatus(d.id,{local:IS_MOBILE_DEVICE?'ok':(force?(backupRootHandle?'pending':'setup'):(st.local==='ok'?'ok':(backupRootHandle?'pending':'setup'))),cloud:force?(cloudIsConnected()?'pending':'setup'):(st.cloud==='ok'?'ok':(cloudIsConnected()?'pending':'setup'))})}
  for(const d of getQuotes()){const st=getDocBackupStatus(d.id);updateDocBackupStatus(d.id,{local:IS_MOBILE_DEVICE?'ok':(force?(backupRootHandle?'pending':'setup'):(st.local==='ok'?'ok':(backupRootHandle?'pending':'setup'))),cloud:force?(cloudIsConnected()?'pending':'setup'):(st.cloud==='ok'?'ok':(cloudIsConnected()?'pending':'setup'))})}
}
function scheduleBackupProcessing(delay=350){clearTimeout(backupTimer);backupTimer=setTimeout(()=>processBackupQueue(),delay)}

function openFsHandleDb(){return new Promise((resolve,reject)=>{const req=indexedDB.open(FS_DB_NAME,1);req.onupgradeneeded=()=>{if(!req.result.objectStoreNames.contains(FS_DB_STORE))req.result.createObjectStore(FS_DB_STORE)};req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error)})}
async function storeFsHandle(key,handle){const db=await openFsHandleDb();return new Promise((resolve,reject)=>{const tx=db.transaction(FS_DB_STORE,'readwrite');tx.objectStore(FS_DB_STORE).put(handle,key);tx.oncomplete=()=>{db.close();resolve()};tx.onerror=()=>{db.close();reject(tx.error)}})}
async function loadFsHandle(key){const db=await openFsHandleDb();return new Promise((resolve,reject)=>{const tx=db.transaction(FS_DB_STORE,'readonly'),req=tx.objectStore(FS_DB_STORE).get(key);req.onsuccess=()=>{const v=req.result;db.close();resolve(v||null)};req.onerror=()=>{db.close();reject(req.error)}})}
async function handlePermission(handle,request=false){if(!handle)return 'denied';try{if(!handle.queryPermission)return 'granted';let p=await handle.queryPermission({mode:'readwrite'});if(p==='prompt'&&request&&handle.requestPermission)p=await handle.requestPermission({mode:'readwrite'});return p}catch{return 'denied'}}
async function chooseBackupFolder(){
  if(!window.showDirectoryPicker){alert('Este navegador no permite guardar automáticamente en una carpeta. Usa Microsoft Edge o Google Chrome actualizado.');return}
  try{
    const h=await window.showDirectoryPicker({id:'brinky-fiesta-suite-backup',mode:'readwrite'});
    const permission=await handlePermission(h,true);if(permission!=='granted')throw new Error('No se concedió permiso de escritura.');
    backupRootHandle=h;await storeFsHandle(FS_ROOT_KEY,h);await tryRestoreMasterSnapshotFromFolder();queueAllCurrentDocuments(true);updateBackupUi();await processBackupQueue();await writeMasterSnapshotToFolder().catch(()=>{});
    alert(`Carpeta local configurada: ${h.name}.\n\nAdemás de PDF + JSON, v2.2.3 guardará un respaldo completo de la Suite en esta carpeta.`);
  }catch(err){if(err?.name!=='AbortError')alert('No se pudo configurar la carpeta local: '+(err?.message||err));updateBackupUi()}
}
async function ensureBackupRootPermission(request=false){if(!backupRootHandle)return false;return (await handlePermission(backupRootHandle,request))==='granted'}
function safeBackupName(data){return `${data.id} - ${data.clientName||'SIN NOMBRE'}`.replace(/[<>:"/\\|?*\x00-\x1F]/g,'_').replace(/\s+/g,' ').trim().slice(0,150)}
async function childDir(parent,name){return parent.getDirectoryHandle(name,{create:true})}
async function writeHandleFile(dir,name,blob){const fh=await dir.getFileHandle(name,{create:true}),w=await fh.createWritable();await w.write(blob);await w.close()}
async function backupDocumentToFolder(type,data,pdfFile){
  if(!backupRootHandle)throw new Error('Carpeta local no configurada');
  if(!(await ensureBackupRootPermission(false)))throw Object.assign(new Error('La carpeta necesita autorización nuevamente.'),{code:'PERMISSION'});
  const folderName=type==='contract'?'Contratos':'Cotizaciones';
  const year=(String(data.id).match(/-(\d{4})-/)||[])[1]||String(new Date().getFullYear());
  const rootType=await childDir(backupRootHandle,folderName),yearDir=await childDir(rootType,year),dataDir=await childDir(yearDir,'Datos');
  const base=safeBackupName(data);
  await writeHandleFile(yearDir,`${base}.pdf`,pdfFile);
  const json=new Blob([JSON.stringify({backupFormat:'BRINKY_FIESTA_SUITE_V1',documentType:type,savedAt:new Date().toISOString(),data},null,2)],{type:'application/json'});
  await writeHandleFile(dataDir,`${base}.json`,json);
  return `${folderName}/${year}/${base}.pdf`;
}

function normalizeCloudUrl(v=''){return String(v).trim().replace(/\/+$/,'')}
function getCloudConfig(){try{return JSON.parse(localStorage.getItem(CLOUD_CONFIG_KEY)||'{}')}catch{return{}}}
function setCloudConfig(c){localStorage.setItem(CLOUD_CONFIG_KEY,JSON.stringify(c));updateBackupUi()}
function getCloudSession(){try{return JSON.parse(localStorage.getItem(CLOUD_SESSION_KEY)||'null')}catch{return null}}
function setCloudSession(s){if(s)localStorage.setItem(CLOUD_SESSION_KEY,JSON.stringify(s));else localStorage.removeItem(CLOUD_SESSION_KEY);updateBackupUi()}
function cloudIsConnected(){const c=getCloudConfig(),s=getCloudSession();return Boolean(c.url&&c.anonKey&&s?.access_token&&s?.user?.id)}
function cloudHeaders(extra={},session=null){const c=getCloudConfig(),s=session||getCloudSession();return {'apikey':c.anonKey||'','Authorization':`Bearer ${s?.access_token||c.anonKey||''}`,...extra}}
async function cloudAuthFetch(path,body){const c=getCloudConfig();if(!c.url||!c.anonKey)throw new Error('Falta configurar URL y clave pública de Supabase.');const r=await fetch(`${c.url}${path}`,{method:'POST',headers:{'apikey':c.anonKey,'Authorization':`Bearer ${c.anonKey}`,'Content-Type':'application/json'},body:JSON.stringify(body)});const txt=await r.text();let data={};try{data=txt?JSON.parse(txt):{}}catch{}if(!r.ok)throw new Error(data?.msg||data?.message||data?.error_description||txt||`Error ${r.status}`);return data}
function normalizeCloudSession(data){if(!data?.access_token)return null;return{access_token:data.access_token,refresh_token:data.refresh_token,expires_at:Date.now()+Math.max(30,Number(data.expires_in||3600)-60)*1000,user:data.user||getCloudSession()?.user||null}}
async function refreshCloudSession(){const c=getCloudConfig(),s=getCloudSession();if(!c.url||!c.anonKey||!s?.refresh_token)return null;try{const data=await cloudAuthFetch('/auth/v1/token?grant_type=refresh_token',{refresh_token:s.refresh_token});const ns=normalizeCloudSession(data);if(ns)setCloudSession(ns);return ns}catch(err){setCloudSession(null);throw err}}
async function ensureCloudSession(){let s=getCloudSession();if(!s?.access_token)return null;if(!s.expires_at||Date.now()>Number(s.expires_at)-30000)s=await refreshCloudSession();return s}
async function cloudFetch(path,options={},retry=true){
  const c=getCloudConfig();let s=await ensureCloudSession();if(!c.url||!c.anonKey||!s?.access_token)throw new Error('Nube no conectada.');
  const headers=cloudHeaders(options.headers||{},s),r=await fetch(`${c.url}${path}`,{...options,headers});
  if(r.status===401&&retry){s=await refreshCloudSession();if(s)return cloudFetch(path,options,false)}
  if(!r.ok){const t=await r.text();throw new Error(t||`Error de nube ${r.status}`)}return r;
}
function readCloudConfigForm(){return{url:normalizeCloudUrl($('cloudProjectUrl')?.value),anonKey:String($('cloudAnonKey')?.value||'').trim(),email:String($('cloudEmail')?.value||'').trim()}}
function persistCloudForm(){const c=readCloudConfigForm();if(!c.url||!c.anonKey)throw new Error('Completa Project URL y Anon / Publishable key.');setCloudConfig(c);return c}
