const canvas=$('signatureCanvas'),ctx=canvas.getContext('2d');let drawing=false;
function resizeCanvas(forceClear=false){
  const ratio=Math.max(window.devicePixelRatio||1,1),rect=canvas.getBoundingClientRect();
  const old=forceClear?'':canvas.toDataURL();
  canvas.width=Math.max(1,rect.width*ratio);canvas.height=Math.max(1,rect.height*ratio);ctx.setTransform(ratio,0,0,ratio,0,0);ctx.lineWidth=2.2;ctx.lineCap='round';ctx.strokeStyle='#111';
  if(old){const img=new Image();img.onload=()=>ctx.drawImage(img,0,0,rect.width,rect.height);img.src=old}
}
function clearSignatureCanvas(){const rect=canvas.getBoundingClientRect();ctx.clearRect(0,0,rect.width||canvas.width,rect.height||canvas.height)}
function pos(e){const r=canvas.getBoundingClientRect(),p=e.touches?e.touches[0]:e;return{x:p.clientX-r.left,y:p.clientY-r.top}}
function start(e){drawing=true;const p=pos(e);ctx.beginPath();ctx.moveTo(p.x,p.y);e.preventDefault()}
function move(e){if(!drawing)return;const p=pos(e);ctx.lineTo(p.x,p.y);ctx.stroke();e.preventDefault()}
function end(){drawing=false}
['mousedown','touchstart'].forEach(x=>canvas.addEventListener(x,start,{passive:false}));
['mousemove','touchmove'].forEach(x=>canvas.addEventListener(x,move,{passive:false}));
['mouseup','mouseleave','touchend'].forEach(x=>canvas.addEventListener(x,end));
