function drawWrappedText(g,text,x,y,maxWidth,lineHeight,maxLines=99){
  const words=String(text||'').split(/\s+/);let line='',lines=[];
  for(const word of words){const test=line?line+' '+word:word;if(g.measureText(test).width>maxWidth&&line){lines.push(line);line=word}else line=test}
  if(line)lines.push(line);lines=lines.slice(0,maxLines);lines.forEach((ln,i)=>g.fillText(ln,x,y+i*lineHeight));return y+lines.length*lineHeight;
}
