function normalizeReferralCode(value=''){
  return String(value||'').trim().toUpperCase().replace(/\s+/g,'');
}
function migrateLegacyClubIfAvailable(){
  if(localStorage.getItem(LOYALTY_KEY))return;
  const legacy=localStorage.getItem(LEGACY_LOYALTY_KEY);if(!legacy)return;
  try{
    const items=JSON.parse(legacy);if(!Array.isArray(items)||!items.length)return;
    let max=items.reduce((m,c)=>Math.max(m,Number(String(c.code||'').replace(/\D/g,''))||0),0),seen=new Set();
    for(const c of items){let code=normalizeReferralCode(c.code);if(!/^BRK-\d{4,}$/.test(code)||seen.has(code)){max++;code='BRK-'+String(max).padStart(4,'0');c.code=code;c.history=Array.isArray(c.history)?c.history:[];c.history.unshift({date:new Date().toISOString(),type:'migration',text:'Código ajustado durante migración segura a Brinky Fiesta Suite v2.0.1.'})}seen.add(code)}
    localStorage.setItem(LOYALTY_KEY,JSON.stringify(items));localStorage.setItem(LOYALTY_FOLIO_KEY,String(max));
    const settings=localStorage.getItem(LEGACY_LOYALTY_SETTINGS_KEY);if(settings&&!localStorage.getItem(LOYALTY_SETTINGS_KEY))localStorage.setItem(LOYALTY_SETTINGS_KEY,settings);
    localStorage.setItem(CLUB_CLOUD_PENDING_KEY,'1');
  }catch(err){console.warn('No se pudo migrar Club Brinky anterior:',err)}
}
