  c={id:crypto.randomUUID?.()||('LC-'+Date.now()+'-'+Math.random().toString(36).slice(2,7)),code:nextLoyaltyCode(),name:name||'Cliente',phone:phone||'',birthday:'',notes:'',stamps:0,totalRents:0,totalSpent:0,referrals:0,referredBy:'',reward50Used:false,lastMessageType:'welcome',history:[],rewardHistory:[],createdAt:new Date().toISOString(),updatedAt:new Date().toISOString()};
