function validateContractReferralCode(){
  const input=$('contractReferralCode');if(!input)return true;
  const code=normalizeReferralCode(input.value);input.value=code;
  if(!code){setContractReferralStatus('neutral','Puedes dejarlo vacío. Si escribes un código, se validará contra Club Brinky.');return true}
  const member=getLoyalty().find(c=>normalizeReferralCode(c.code)===code);
  if(!member){setContractReferralStatus('invalid','❌ Código no encontrado en Club Brinky.');return false}
  const phone=normalizedPhone($('clientPhone')?.value||'');
  if(phone&&normalizedPhone(member.phone)===phone){setContractReferralStatus('invalid','⚠️ El cliente no puede usar su propio código.');return false}
  const existing=phone?getLoyalty().find(c=>normalizedPhone(c.phone)===phone):null;
  if(existing?.referredBy&&existing.referredBy!==member.id){setContractReferralStatus('invalid','⚠️ Este cliente ya fue registrado con otro socio que lo recomendó.');return false}
  const already=getContracts().some(c=>c.id!==editingContractId&&c.referralRewarded&&phone&&normalizedPhone(c.clientPhone)===phone);
  if(already){setContractReferralStatus('invalid','⚠️ Este cliente ya recibió anteriormente el beneficio por referido.');return false}
  setContractReferralStatus('valid',`✅ Código válido: ${member.name}`,member);return true;
}
